CREATE TABLE IF NOT EXISTS cache_carne (
    producto    TEXT PRIMARY KEY,
    es_carne    BOOLEAN NOT NULL,
    creado_en   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
